int ax25_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t size, int flags)
{
    int err;
    struct sock *sk = sock->sk;
    struct ax25_cb *ax25;
    struct sk_buff *skb;

    lock_sock(sk);

    if (sk->sk_type == SOCK_SEQPACKET && sk->sk_state != TCP_ESTABLISHED) {
        err = -EWOULDBLOCK;
        goto out;
    }

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb) {
        err = -EWOULDBLOCK;
        goto out;
    }

    ax25 = ax25_sk(sk);

    msg->msg_namelen = sizeof(struct sockaddr_ax25);
    if (ax25->neighbour) {
        struct sockaddr_ax25 *sax = (struct sockaddr_ax25 *)msg->msg_name;
        sax->sax25_family = AF_AX25;
        memcpy(sax->sax25_call.ax25_call, ax25->neighbour->callsign,
               AX25_ADDR_LEN);
    }

    err = skb->len;
    if (err > size)
        err = size;

    if (memcpy_to_msg(msg, skb->data, err) < 0) {
        kfree_skb(skb);
        goto out;
    }

    kfree_skb(skb);

out:
    release_sock(sk);
    return err;
}

